/* --- js/utils.js --- */
(() => {
  "use strict";

  const doc = document;
  const win = window;

  const $ = (selector, parent = doc) => {
    if (!parent) return null;
    return parent.querySelector(selector);
  };

  const $$ = (selector, parent = doc) => {
    if (!parent) return [];
    return Array.from(parent.querySelectorAll(selector));
  };

  const on = (element, event, callback) => {
    if (!element || typeof callback !== "function") return;

    element.addEventListener(event, callback, { passive: true });
  };

  const debounce = (func, delay = 300) => {
    let timer = null;

    return (...args) => {
      if (timer) clearTimeout(timer);

      timer = window.setTimeout(() => {
        func.apply(null, args);
      }, delay);
    };
  };

  const throttle = (func, limit = 100) => {
    let waiting = false;
    let frame = null;

    return (...args) => {
      if (waiting) {
        if (frame) cancelAnimationFrame(frame);

        frame = requestAnimationFrame(() => {
          waiting = false;
          func.apply(null, args);
        });

        return;
      }

      waiting = true;
      func.apply(null, args);

      window.setTimeout(() => {
        waiting = false;
      }, limit);
    };
  };

  const raf = (callback) => {
    return window.requestAnimationFrame(callback);
  };

  const storage = {
    set(key, value) {
      try {
        localStorage.setItem(key, JSON.stringify(value));
      } catch (error) {
        console.warn("Storage unavailable", error);
      }
    },

    get(key) {
      try {
        const data = localStorage.getItem(key);
        return data ? JSON.parse(data) : null;
      } catch (error) {
        console.warn("Storage read failed", error);
        return null;
      }
    },

    remove(key) {
      try {
        localStorage.removeItem(key);
      } catch (error) {
        console.warn("Storage removal failed", error);
      }
    },
  };

  const isMobile = () => {
    return (
      win.matchMedia("(max-width: 768px)").matches || win.innerWidth <= 768
    );
  };

  const isReducedMotion = () => {
    return win.matchMedia("(prefers-reduced-motion: reduce)").matches;
  };

  const scrollToTop = (behavior = "smooth") => {
    win.scrollTo({ top: 0, behavior });
  };

  win.Utils = {
    $,
    $$,
    on,
    debounce,
    throttle,
    raf,
    storage,
    isMobile,
    isReducedMotion,
    scrollToTop,
  };
})();

/* --- js/loader.js --- */
(() => {
  "use strict";

  const loader = document.querySelector(".loader");

  if (!loader) return;

  let loaderHidden = false;

  const setBodyOverflow = (hidden) => {
    document.body.style.overflow = hidden ? "hidden" : "";
  };

  const hideLoader = () => {
    if (loaderHidden) return;

    loaderHidden = true;

    loader.classList.add("hidden");
    document.documentElement.classList.remove("loading");
    setBodyOverflow(false);

    window.setTimeout(() => {
      loader.remove();
    }, 600);
  };

  const initLoader = () => {
    document.documentElement.classList.add("loading");
    setBodyOverflow(true);

    if (document.readyState === "complete") {
      hideLoader();
      return;
    }

    window.addEventListener("load", hideLoader, { once: true });
    window.setTimeout(hideLoader, 3500);
  };

  initLoader();
})();

/* --- js/navigation.js --- */
(() => {
  "use strict";

  const header = document.querySelector(".header");
  const allNavLinks = document.querySelectorAll(".nav-link, .mobile-menu a");
  const sections = document.querySelectorAll("section");

  const menuToggle = document.querySelector(".menu-toggle");
  const mobileMenu = document.querySelector(".mobile-menu");
  const menuClose = document.querySelector("#menu-close");
  const mobileLinks = document.querySelectorAll(".mobile-menu a");
  const backToTop = document.querySelector(".back-to-top");

  const handleHeader = () => {
    if (!header) return;
    header.classList.toggle("scrolled", window.scrollY > 50);
  };

  const updateActiveLink = () => {
    let current = "";
    const offset = window.scrollY + 180;

    sections.forEach((section) => {
      const sectionTop = section.offsetTop;
      const sectionHeight = section.offsetHeight;

      if (offset >= sectionTop && offset < sectionTop + sectionHeight) {
        current = section.id;
      }
    });

    allNavLinks.forEach((link) => {
      const isActive = link.getAttribute("href") === `#${current}`;
      link.classList.toggle("active", isActive);
      link.setAttribute("aria-current", isActive ? "page" : "false");
    });
  };

  const closeMenu = () => {
    if (!mobileMenu || !menuToggle) return;

    mobileMenu.classList.remove("active");
    document.body.classList.remove("menu-open");

    menuToggle.setAttribute("aria-expanded", "false");
    mobileMenu.setAttribute("aria-hidden", "true");

    menuToggle.focus();
  };

  const toggleMenu = () => {
    if (!mobileMenu || !menuToggle) return;

    const isOpen = mobileMenu.classList.toggle("active");

    document.body.classList.toggle("menu-open", isOpen);
    menuToggle.setAttribute("aria-expanded", String(isOpen));
    mobileMenu.setAttribute("aria-hidden", String(!isOpen));
  };

  if (menuToggle) {
    menuToggle.addEventListener("click", (event) => {
      event.stopPropagation();
      toggleMenu();
    });
  }

  document.addEventListener("click", (event) => {
    if (!mobileMenu || !menuToggle) return;

    if (
      mobileMenu.classList.contains("active") &&
      !mobileMenu.contains(event.target) &&
      !menuToggle.contains(event.target)
    ) {
      closeMenu();
    }
  });

  if (menuClose) {
    menuClose.addEventListener("click", (event) => {
      event.stopPropagation();
      closeMenu();
    });
  }
  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape") {
      closeMenu();
    }
  });

  mobileLinks.forEach((link) => {
    link.addEventListener("click", closeMenu);
  });

  const handleBackTop = () => {
    if (!backToTop) return;
    backToTop.classList.toggle("show", window.scrollY > 500);
  };

  if (backToTop) {
    backToTop.addEventListener("click", () => {
      window.scrollTo({ top: 0, behavior: "smooth" });
    });
  }

  const themeToggle = document.querySelector(".theme-toggle");
  const themeIcon = themeToggle?.querySelector("i");
  const THEME_KEY = CONFIG.theme.storageKey;
  const DEFAULT_THEME = CONFIG.theme.default;

  const updateThemeIcon = () => {
    if (!themeIcon) return;

    themeIcon.className = document.body.classList.contains("light-theme")
      ? "fa-solid fa-sun"
      : "fa-solid fa-moon";
  };

  const savedTheme = Utils.storage.get(THEME_KEY) || DEFAULT_THEME;

  if (savedTheme === "light") {
    document.body.classList.add("light-theme");
  }

  updateThemeIcon();

  if (themeToggle) {
    themeToggle.addEventListener("click", () => {
      document.body.classList.toggle("light-theme");

      const currentTheme = document.body.classList.contains("light-theme")
        ? "light"
        : "dark";
      Utils.storage.set(THEME_KEY, currentTheme);
      updateThemeIcon();
    });
  }

  const optimizedScroll = Utils.throttle(() => {
    handleHeader();
    updateActiveLink();
    handleBackTop();
  }, 100);

  window.addEventListener("scroll", optimizedScroll, { passive: true });

  handleHeader();
  updateActiveLink();
  handleBackTop();

  const footer = document.querySelector(".footer");

  if (footer && backToTop) {
    const footerObserver = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        backToTop.classList.toggle("footer-visible", entry.isIntersecting);
      });
    });

    footerObserver.observe(footer);
  }
})();

/* --- js/animations.js --- */
(() => {
  "use strict";

  const reducedMotion = Utils.isReducedMotion();

  const revealElements = document.querySelectorAll(".reveal");

  if (revealElements.length) {
    if (reducedMotion) {
      revealElements.forEach((element) => element.classList.add("active"));
    } else {
      const revealObserver = new IntersectionObserver(
        (entries, observer) => {
          entries.forEach((entry) => {
            if (!entry.isIntersecting) return;

            entry.target.classList.add("active");
            observer.unobserve(entry.target);
          });
        },
        { threshold: 0.15 },
      );

      revealElements.forEach((element) => revealObserver.observe(element));
    }
  }

  const counters = document.querySelectorAll(".stat-number");

  const animateCounter = (element) => {
    const target = Number(element.dataset.count || element.dataset.target || 0);
    let current = 0;
    const speed = target / CONFIG.animation.counterSpeed;

    const update = () => {
      current += speed;

      if (current < target) {
        element.textContent = Math.floor(current);
        Utils.raf(update);
      } else {
        element.textContent = target;
      }
    };

    update();
  };

  if (counters.length) {
    if (reducedMotion) {
      counters.forEach((counter) => {
        counter.textContent =
          counter.dataset.count ||
          counter.dataset.target ||
          counter.textContent;
      });
    } else {
      const counterObserver = new IntersectionObserver(
        (entries, observer) => {
          entries.forEach((entry) => {
            if (!entry.isIntersecting) return;

            animateCounter(entry.target);
            observer.unobserve(entry.target);
          });
        },
        { threshold: 0.5 },
      );

      counters.forEach((counter) => counterObserver.observe(counter));
    }
  }

  const typeElement = document.querySelector(".typewriter");

  if (typeElement) {
    const text = typeElement.dataset.text || "";

    if (reducedMotion) {
      typeElement.textContent = text;
    } else {
      typeElement.textContent = "";

      if (text) {
        let index = 0;
        const speed = CONFIG.animation.typeSpeed || 80;

        const typing = () => {
          if (index >= text.length) return;
          typeElement.textContent += text.charAt(index++);
          window.setTimeout(typing, speed);
        };

        typing();
      }
    }
  }

  document.querySelectorAll(".magnetic").forEach((button) => {
    button.addEventListener(
      "mousemove",
      (event) => {
        const rect = button.getBoundingClientRect();
        const x = event.clientX - rect.left - rect.width / 2;
        const y = event.clientY - rect.top - rect.height / 2;

        Utils.raf(() => {
          button.style.transform = `translate(${x * 0.15}px, ${y * 0.15}px)`;
        });
      },
      { passive: true },
    );

    button.addEventListener("mouseleave", () => {
      button.style.transform = "";
    });
  });

  document.querySelectorAll(".tilt-card").forEach((card) => {
    card.addEventListener(
      "mousemove",
      (event) => {
        const rect = card.getBoundingClientRect();
        const rotateX = (event.clientY - rect.top - rect.height / 2) / 20;
        const rotateY = (rect.width / 2 - (event.clientX - rect.left)) / 20;

        Utils.raf(() => {
          card.style.transform = `perspective(1000px) rotateX(${rotateX}deg) rotateY(${rotateY}deg) translateY(-10px)`;
        });
      },
      { passive: true },
    );

    card.addEventListener("mouseleave", () => {
      card.style.transform = "";
    });
  });
})();

/* --- js/cursor.js --- */
(() => {
  "use strict";

  const isDesktop = window.matchMedia(
    "(hover: hover) and (pointer: fine)",
  ).matches;

  if (!isDesktop) return;

  const cursor = document.createElement("div");
  const cursorGlow = document.createElement("div");

  cursor.className = "custom-cursor";
  cursorGlow.className = "cursor-glow";
  cursor.style.pointerEvents = "none";
  cursorGlow.style.pointerEvents = "none";

  document.body.append(cursor, cursorGlow);

  let mouseX = 0;
  let mouseY = 0;
  let cursorX = 0;
  let cursorY = 0;

  window.addEventListener(
    "mousemove",
    (event) => {
      mouseX = event.clientX;
      mouseY = event.clientY;
    },
    { passive: true },
  );

  const animateCursor = () => {
    cursorX += (mouseX - cursorX) * 0.15;
    cursorY += (mouseY - cursorY) * 0.15;

    cursor.style.transform = `translate3d(${cursorX}px, ${cursorY}px, 0)`;
    cursorGlow.style.transform = `translate3d(${mouseX}px, ${mouseY}px, 0)`;

    window.requestAnimationFrame(animateCursor);
  };

  animateCursor();

  document.addEventListener("mouseover", (event) => {
    const target = event.target;
    const interactive =
      target instanceof Element &&
      target.closest("a, button, .btn, .magnetic, .tilt-card");
    cursor.classList.toggle("active", Boolean(interactive));
  });

  document.addEventListener("mouseout", () => {
    cursor.classList.remove("active");
  });

  const toggleCursor = (show) => {
    const opacity = show ? "1" : "0";
    cursor.style.opacity = opacity;
    cursorGlow.style.opacity = opacity;
  };

  document.addEventListener("mouseleave", () => toggleCursor(false));
  document.addEventListener("mouseenter", () => toggleCursor(true));
  window.addEventListener("blur", () => toggleCursor(false));
  window.addEventListener("focus", () => toggleCursor(true));
})();

/* --- js/particles.js --- */
(() => {
  "use strict";

  const CONTAINER_ID = "tsparticles";
  const reducedMotion = window.matchMedia(
    "(prefers-reduced-motion: reduce)",
  ).matches;

  const hasContainer = document.getElementById(CONTAINER_ID);
  const hasLibrary = typeof window.tsParticles !== "undefined";

  if (!hasContainer || !hasLibrary || reducedMotion) return;

  window.tsParticles.load(CONTAINER_ID, {
    fullScreen: false,
    background: { color: "transparent" },
    fpsLimit: 60,
    detectRetina: true,

    particles: {
      number: {
        value: 30,
        density: { enable: true, area: 1200 },
      },
      color: { value: ["#7C3AED", "#06B6D4", "#22C55E"] },
      links: { enable: false },
      move: {
        enable: true,
        speed: 0.6,
        direction: "none",
        random: true,
        straight: false,
        outModes: { default: "out" },
      },
      opacity: {
        value: 0.25,
        animation: { enable: true, speed: 0.3, minimumValue: 0.08 },
      },
      shape: { type: "circle" },
      size: { value: { min: 2, max: 6 } },
    },

    interactivity: {
      detectsOn: "window",
      events: {
        resize: true,
        onHover: { enable: true, mode: "bubble" },
      },
      modes: {
        bubble: { distance: 120, duration: 1, opacity: 0.8, size: 8 },
      },
    },
  });
})();

/* --- js/contact.js --- */
(() => {
  "use strict";

  if (!window.emailjs || !window.Swal) return;

  const { publicKey, serviceId, templateId } = CONFIG.emailjs;
  const form = document.querySelector("#contact-form");

  if (!form) return;

  const submitButton = form.querySelector('button[type="submit"]');
  if (!submitButton) return;

  const defaultButtonHTML = submitButton.innerHTML;

  emailjs.init({ publicKey });

  const trim = (value) => (value || "").trim();

  const validateForm = () => {
    const name = trim(form.name.value);
    const email = trim(form.email.value);
    const subject = trim(form.subject.value);
    const message = trim(form.message.value);
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

    if (!name || !email || !subject || !message) {
      Swal.fire({
        icon: "warning",
        title: "Missing Information",
        text: "Please fill in all fields before sending.",
      });
      return false;
    }

    if (!emailRegex.test(email)) {
      Swal.fire({
        icon: "error",
        title: "Invalid Email",
        text: "Please enter a valid email address.",
      });
      return false;
    }

    return true;
  };

  const setLoading = (loading) => {
    submitButton.disabled = loading;
    submitButton.setAttribute("aria-busy", String(loading));
    submitButton.innerHTML = loading
      ? '<i class="fa-solid fa-spinner fa-spin"></i> Sending...'
      : defaultButtonHTML;
  };

  let lastSubmit = 0;

  const canSubmit = () => {
    const now = Date.now();

    if (now - lastSubmit < 10000) {
      Swal.fire({
        icon: "info",
        title: "Please Wait",
        text: "You can send another message in a few seconds.",
      });
      return false;
    }

    lastSubmit = now;
    return true;
  };

  form.addEventListener("submit", async (event) => {
    event.preventDefault();

    if (!validateForm() || !canSubmit()) return;

    setLoading(true);

    try {
      await emailjs.sendForm(serviceId, templateId, form);

      Swal.fire({
        icon: "success",
        title: "Message Sent",
        text: "Thank you! I'll get back to you soon.",
        confirmButtonColor: "#7C3AED",
      });

      form.reset();
    } catch (error) {
      console.error("[EmailJS]", error);

      Swal.fire({
        icon: "error",
        title: "Failed",
        text: "Unable to send your message right now. Please try again later.",
      });
    } finally {
      setLoading(false);
    }
  });
})();

/* --- js/main.js --- */
(() => {
  "use strict";

  const APP = {
    initialized: false,
    ticking: false,
  };

  const progressBar = document.querySelector(".progress__bar");

  const updateScrollProgress = () => {
    if (!progressBar) return;

    const scrollTop = window.scrollY;
    const documentHeight =
      document.documentElement.scrollHeight - window.innerHeight;
    const progress =
      documentHeight > 0 ? (scrollTop / documentHeight) * 100 : 0;

    progressBar.style.width = `${Math.min(100, Math.max(0, progress))}%`;
  };

  const handleScroll = () => {
    if (APP.ticking) return;

    APP.ticking = true;

    window.requestAnimationFrame(() => {
      updateScrollProgress();
      APP.ticking = false;
    });
  };

  const handleResize = Utils.debounce(() => {
    updateScrollProgress();
  }, 150);

  const init = () => {
    if (APP.initialized) return;

    APP.initialized = true;

    updateScrollProgress();

    window.addEventListener("scroll", handleScroll, { passive: true });
    window.addEventListener("resize", handleResize);

    window.addEventListener("error", (event) => {
      console.error("[Portfolio Error]", event.message);
    });

    window.addEventListener("unhandledrejection", (event) => {
      console.error("[Promise Error]", event.reason);
    });

    document.documentElement.classList.add("js-ready");
    document.body.setAttribute(
      "data-theme",
      document.body.classList.contains("light-theme") ? "light" : "dark",
    );
  };

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init, { once: true });
  } else {
    init();
  }
})();
